package com.example.yudreamui.protocol;
import com.google.gson.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class FallbackPlanTest {
 private String html="<html><head/><body><p bind='balance' fallback-label='余额'>120</p><mc-input id='note' maxlength='12'/><mc-checkbox id='check'/><mc-slider id='level' min='0' max='10' value='5'/><mc-button id='save' aria-label='保存' action='server:save' input-ids='note check level'>Save</mc-button><mc-button id='buy' action='server:buy'>购买</mc-button></body></html>";
 @Test void semanticViewPreservesBindingAndTypedInputs(){var plan=FallbackPlan.fromHtml(html,"店铺");assertEquals(1,plan.schema());assertEquals(2,plan.buttons().size());assertEquals(3,plan.fields().size());var state=new JsonObject();state.addProperty("balance",110);assertEquals("余额：110",plan.renderBody(state));var form=JsonParser.parseString("{\"note\":\"小镇\",\"check\":true,\"level\":7,\"ignored\":123}").getAsJsonObject();assertEquals(3,plan.validate("save","server:save",form).size());assertTrue(plan.validate("buy","server:buy",form).isEmpty());}
 @Test void staleOrForgedControlAndInvalidFormAreRejected(){var p=FallbackPlan.fromHtml(html,"店铺");assertThrows(IllegalArgumentException.class,()->p.validate("buy","server:save",new JsonObject()));assertThrows(IllegalArgumentException.class,()->p.validate("save","server:save",new JsonObject()));var form=JsonParser.parseString("{\"note\":\"x\",\"check\":\"true\",\"level\":7}").getAsJsonObject();assertThrows(IllegalArgumentException.class,()->p.validate("save","server:save",form));form.addProperty("check",true);form.addProperty("level",11);assertThrows(IllegalArgumentException.class,()->p.validate("save","server:save",form));}
 @Test void invalidReferencesAndUnsupportedSchemaFail(){assertThrows(IllegalArgumentException.class,()->FallbackPlan.fromHtml(html.replace("note check level","missing"),"店铺"));assertThrows(IllegalArgumentException.class,()->FallbackPlan.fromHtml(html.replace("id='buy'","id='save'"),"店铺"));}
 @Test void invalidDefaultsAndAmbiguousNativeIdsAreRejected(){assertThrows(IllegalArgumentException.class,()->FallbackPlan.fromHtml(html.replace("value='5'","value='999'"),"店铺"));assertThrows(IllegalArgumentException.class,()->HtmlCompiler.compile("<html><head/><body><p id='same'/><div id='same'/></body></html>",""));assertThrows(IllegalArgumentException.class,()->HtmlCompiler.compile(html.replace("server:buy","javascript:buy"),""));}
}
